/**
 * Pre-generate the Prisma 7 clients for every schema variant into
 * src/generated/<variant>/ (compiled into lib/generated by tsc and shipped,
 * so consumers never run `prisma generate`). Variants are derived from the
 * prisma/ directory itself — adding schema.<db>.prisma is the only edit
 * needed. Runs the workspace-pinned prisma CLI; generated output is
 * gitignored and rebuilt by `pnpm build`.
 */

import { execFileSync } from 'node:child_process';
import { readdirSync } from 'node:fs';

const variants = readdirSync('prisma')
  .filter((f) => /^schema\..+\.prisma$/.test(f))
  .map((f) => f.slice('schema.'.length, -'.prisma'.length))
  .sort();

for (const variant of variants) {
  console.log(`prisma generate: ${variant}`);
  execFileSync('pnpm', ['exec', 'prisma', 'generate', '--schema', `prisma/schema.${variant}.prisma`], {
    stdio: 'inherit',
  });
}
